mapper.select:
SELECT ucc.config_id, ucc.user_id, ucc.username, ucc.real_name, ucc.user_type, CASE ucc.user_type WHEN 1 THEN '采购员' WHEN 2 THEN '管理员' ELSE '未知' END AS user_type_name, ucc.commission_type, CASE ucc.commission_type WHEN 1 THEN '固定金额' WHEN 2 THEN '百分比' ELSE '未知' END AS commission_type_name, ucc.commission_value, ucc.min_commission, ucc.max_commission, ucc.effective_time, ucc.expiry_time, ucc.status, CASE ucc.status WHEN 0 THEN '禁用' WHEN 1 THEN '启用' ELSE '未知' END AS status_name, ucc.remark, ucc.created_by, ucc.created_at, ucc.updated_by, ucc.updated_at FROM user_commission_config ucc WHERE ucc.is_deleted = 0
AND ucc.user_type = #{userType}
AND ucc.status = #{status}
AND (ucc.username LIKE CONCAT('%', #{keyword}, '%') OR ucc.real_name LIKE CONCAT('%', #{keyword}, '%') OR ucc.remark LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ucc.created_at DESC

